From 24c0dbe351acff33db1d2207595d88f1ce21e5bd Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:37:20 +0100
Subject: [PATCH] effects/sessionquit: fade the desktop to black when logging
 out

KWin read the session states from ksmserver off by one, so it was never
in the quitting state at the end of a logout. Map them as documented and
fade the wallpaper and panels to black while the session is quitting.

BUG: 447083
---
 .../sessionquit/package/contents/code/main.js | 43 +++++++++++++++++++
 src/sm.cpp                                    |  4 +-
 2 files changed, 45 insertions(+), 2 deletions(-)

diff --git a/src/plugins/sessionquit/package/contents/code/main.js b/src/plugins/sessionquit/package/contents/code/main.js
index 6b73fd90b4..4cef698b65 100644
--- a/src/plugins/sessionquit/package/contents/code/main.js
+++ b/src/plugins/sessionquit/package/contents/code/main.js
@@ -10,6 +10,48 @@
 "use strict";

 var quitEffect = {
+    duration: animationTime(400),
+    isShellWindow: function (window) {
+        return window.desktopWindow || window.dock;
+    },
+    fadeToBlack: function (window) {
+        if (!quitEffect.isShellWindow(window)) {
+            return;
+        }
+        if (window.quitAnimation) {
+            if (redirect(window.quitAnimation, Effect.Forward)) {
+                return;
+            }
+            cancel(window.quitAnimation);
+        }
+        window.quitAnimation = set({
+            window: window,
+            duration: quitEffect.duration,
+            type: Effect.Brightness,
+            from: 1.0,
+            to: 0.0
+        });
+    },
+    fadeBack: function (window) {
+        if (!window.quitAnimation) {
+            return;
+        }
+        if (redirect(window.quitAnimation, Effect.Backward)) {
+            return;
+        }
+        cancel(window.quitAnimation);
+        delete window.quitAnimation;
+    },
+    sessionStateChanged: function () {
+        const windows = effects.stackingOrder;
+        for (let i = 0; i < windows.length; ++i) {
+            if (effects.sessionState == Globals.Quitting) {
+                quitEffect.fadeToBlack(windows[i]);
+            } else {
+                quitEffect.fadeBack(windows[i]);
+            }
+        }
+    },
     closed: function (window) {
         if (!window.desktopWindow || effects.sessionState != Globals.Quitting) {
             return;
@@ -26,6 +68,7 @@ var quitEffect = {
         });
     },
     init: function () {
+        effects.sessionStateChanged.connect(quitEffect.sessionStateChanged);
         effects.windowClosed.connect(quitEffect.closed);
     }
 };
diff --git a/src/sm.cpp b/src/sm.cpp
index 7a4591880a..abdd316cb2 100644
--- a/src/sm.cpp
+++ b/src/sm.cpp
@@ -317,10 +317,10 @@ SessionState SessionManager::state() const
 void SessionManager::setState(uint state)
 {
     switch (state) {
-    case 0:
+    case 1:
         setState(SessionState::Saving);
         break;
-    case 1:
+    case 2:
         setState(SessionState::Quitting);
         break;
     default:
